const $=id=>document.getElementById(id),base=window.RTS_SERVER_URL,colors=['#6ceba7','#ec7663','#80afff','#ffd363','#df8aef','#67e3ec','#efad73','#c4ed6b','#b7a2ff','#eeeeee'];
let auth=sessionStorage.getItem('rts-token')||'',playerId='',room=null,selected=[],pending='',seq=Number(sessionStorage.getItem('rts-seq')||0),busy=false,lastGood=0,cam={x:0,y:0,z:.55},team=-1,drag=null;
const sprites={};for(const key of ['buildings','units','terrain']){sprites[key]=new Image();sprites[key].src=`assets/hd_${key}.png`;}
async function api(path,data){const r=await fetch(base+'/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+auth}:{})},body:data===undefined?undefined:JSON.stringify(data),signal:AbortSignal.timeout(8000)});const j=await r.json();if(!r.ok){if(r.status===401){auth='';sessionStorage.removeItem('rts-token');}throw Error(j.error||'Server error');}return j;}
const tell=m=>{$('status').textContent=m;$('event').textContent=m;};
function accept(j){if(j.token){auth=j.token;sessionStorage.setItem('rts-token',auth);seq=0;sessionStorage.setItem('rts-seq','0');}playerId=j.playerId||playerId;if(j.room)room=j.room;lastGood=Date.now();renderRoom();}
async function action(fn){try{await fn();}catch(e){tell(e.message);}}
$('create').onclick=()=>action(async()=>accept(await api('create',{name:$('name').value,capacity:Number($('capacity').value)})));
$('join').onclick=()=>action(async()=>accept(await api('join',{name:$('name').value,code:$('code').value.trim()})));
$('ready').onclick=()=>action(async()=>accept(await api('ready',{ready:!room.players.find(p=>p.id===playerId)?.ready})));
$('start').onclick=()=>action(async()=>accept(await api('start',{})));
async function leave(){await api('leave',{});auth='';room=null;team=-1;sessionStorage.removeItem('rts-token');$('game').hidden=true;$('lobby').hidden=false;$('room').hidden=true;$('entry').hidden=false;tell('You left the room.');}
$('leave').onclick=()=>action(leave);$('surrender').onclick=()=>{if(confirm('Surrender and leave this match?'))action(leave);};
$('copy').onclick=()=>action(async()=>{await navigator.clipboard.writeText(room.code);tell('Room code copied');});
function renderRoom(){if(!room)return;$('entry').hidden=true;$('room').hidden=false;$('roomTitle').textContent=`ROOM ${room.code} · ${room.players.length}/${room.capacity}`;$('players').replaceChildren(...room.players.map((p,i)=>{const li=document.createElement('li');li.style.color=colors[i];li.textContent=`${p.name}${p.id===room.host?' · HOST':''} — ${p.ready?'READY':'NOT READY'}${!p.connected?' · disconnected':''}`;return li;}));$('start').hidden=room.host!==playerId;$('ready').textContent=room.players.find(p=>p.id===playerId)?.ready?'Not ready':'Ready';
 if(room.state){const first=team===-1;team=room.state.players.find(p=>p.id===playerId)?.team??-1;$('lobby').hidden=true;$('game').hidden=false;if(first)home();const p=room.state.players[team];$('oil').textContent=`${Math.floor(p?.oil||0)} RU`;$('match').textContent=`${room.state.players.filter(p=>p.alive).length} commanders remaining`;
 const ended=room.phase==='ended'||!p?.alive;$('result').hidden=!ended;if(ended)$('result').textContent=room.state.winner===team?'VICTORY':room.phase==='ended'?'MATCH ENDED':'HEADQUARTERS DESTROYED — Spectating';}
}
async function order(command){if(!room?.state||Date.now()-lastGood>5000)return tell('Connection lost — waiting for server');seq++;sessionStorage.setItem('rts-seq',String(seq));await action(async()=>{await api('command',{seq,command});tell('Order accepted');});}
for(const b of document.querySelectorAll('[data-train]'))b.onclick=()=>order({type:'train',kind:b.dataset.train});
for(const b of document.querySelectorAll('[data-build]'))b.onclick=()=>{pending=b.dataset.build;tell(`Tap near your base to place ${pending}`);};$('cancel').onclick=()=>{pending='';tell('Placement cancelled');};
$('all').onclick=()=>{selected=room.state.entities.filter(e=>e.team===team&&['infantry','buggy','tank'].includes(e.kind)).map(e=>e.id);$('selection').textContent=`${selected.length} units selected`;};$('hold').onclick=()=>order({type:'hold',ids:selected});
function home(){const h=room?.state?.entities.find(e=>e.team===team&&e.kind==='hq');if(h){cam.x=h.x-450;cam.y=h.y-350;}}$('home').onclick=home;$('zoomIn').onclick=()=>cam.z=Math.min(1.2,cam.z*1.2);$('zoomOut').onclick=()=>cam.z=Math.max(.22,cam.z/1.2);
const canvas=$('map'),ctx=canvas.getContext('2d');const world=(x,y)=>({x:x/cam.z+cam.x,y:y/cam.z+cam.y});
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,ox:e.clientX,oy:e.clientY,moved:false};};
canvas.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.ox,e.clientY-drag.oy)>10)drag.moved=true;if(drag.moved){cam.x-=dx/cam.z;cam.y-=dy/cam.z;cam.x=Math.max(-200,Math.min(2900,cam.x));cam.y=Math.max(-200,Math.min(2900,cam.y));}drag.x=e.clientX;drag.y=e.clientY;};
canvas.onpointerup=e=>{if(!drag||drag.id!==e.pointerId)return;const moved=drag.moved;drag=null;if(moved||!room?.state)return;const p=world(e.clientX,e.clientY);if(pending){order({type:'build',kind:pending,...p});pending='';return;}const near=[...room.state.entities].sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y)).find(v=>Math.hypot(v.x-p.x,v.y-p.y)<(v.kind==='hq'?65:45));if(near?.team===team&&['infantry','buggy','tank'].includes(near.kind)){selected=[near.id];$('selection').textContent=`${near.kind} selected`;}else if(selected.length)order(near&&near.team!==team?{type:'attack',ids:selected,target:near.id}:{type:'move',ids:selected,x:p.x,y:p.y});};canvas.onpointercancel=()=>drag=null;
canvas.onwheel=e=>{e.preventDefault();cam.z=Math.max(.22,Math.min(1.2,cam.z*(e.deltaY<0?1.1:.9)));};
const rows={infantry:0,buggy:1,tank:2},builds={hq:0,barracks:1,factory:2,rig:4,turret:5};
function draw(){requestAnimationFrame(draw);if(!room?.state||$('game').hidden)return;const ratio=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(innerWidth*ratio)||canvas.height!==Math.round(innerHeight*ratio)){canvas.width=Math.round(innerWidth*ratio);canvas.height=Math.round(innerHeight*ratio);}ctx.setTransform(ratio,0,0,ratio,0,0);ctx.fillStyle='#222b20';ctx.fillRect(0,0,innerWidth,innerHeight);ctx.scale(cam.z,cam.z);ctx.translate(-cam.x,-cam.y);ctx.fillStyle='#766c48';ctx.fillRect(0,0,3000,3000);
 if(sprites.terrain.complete&&sprites.terrain.naturalWidth){const pat=ctx.createPattern(sprites.terrain,'repeat');ctx.fillStyle=pat;ctx.fillRect(0,0,3000,3000);ctx.fillStyle='#443c2025';ctx.fillRect(0,0,3000,3000);}
 for(const e of [...room.state.entities].sort((a,b)=>a.y-b.y)){const mobile=e.kind in rows,size=mobile?(e.kind==='infantry'?65:100):190;ctx.strokeStyle=colors[e.team];ctx.lineWidth=selected.includes(e.id)?5:2;ctx.beginPath();ctx.ellipse(e.x,e.y+12,mobile?28:55,mobile?14:26,0,0,7);ctx.stroke();const img=mobile?sprites.units:sprites.buildings;
 if(img.complete&&img.naturalWidth){const sw=img.width/4,sh=img.height/(mobile?4:2),index=mobile?rows[e.kind]:builds[e.kind],sx=mobile?0:index%4,sy=mobile?index:Math.floor(index/4);ctx.drawImage(img,sx*sw,sy*sh,sw,sh,e.x-size/2,e.y-size*.7,size,size);}else{ctx.fillStyle=colors[e.team];ctx.fillRect(e.x-16,e.y-16,32,32);}
 ctx.fillStyle='#142015';ctx.fillRect(e.x-28,e.y-size*.6,56,5);ctx.fillStyle=colors[e.team];ctx.fillRect(e.x-28,e.y-size*.6,56*Math.max(0,e.hp/e.maxHp),5);if(e.queue.length){ctx.fillStyle='#fff';ctx.font='16px sans-serif';ctx.fillText(`Queue: ${e.queue.length}`,e.x-32,e.y+40);}}
 if(Date.now()-lastGood>5000)tell('Connection lost — reconnecting. Commands paused.');}
requestAnimationFrame(draw);
if(!base){tell('Online server deployment is pending. Single-player is available now.');$('entry').querySelectorAll('button').forEach(b=>b.disabled=true);}else{tell('Create a room or enter your friend’s room code.');setInterval(async()=>{if(!auth||busy)return;busy=true;try{accept(await api('state'));}catch(e){tell(e.message);}finally{busy=false;}},300);}
